// ~/.pi/agent/extensions/mcp.ts
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { spawn } from "child_process";
import { createInterface } from "readline";
import { readFileSync, existsSync } from "fs";
import { join, dirname } from "path";
import { homedir } from "os";

// MCP 配置接口
interface MCPServerConfig {
  command: string;
  args: string[];
  env?: Record<string, string>;
}

interface MCPConfig {
  mcpServers: Record<string, MCPServerConfig & { enabled?: boolean }>;
}

// JSON-RPC 消息
interface JSONRPCRequest {
  jsonrpc: "2.0";
  id: number;
  method: string;
  params?: unknown;
}

interface JSONRPCResponse {
  jsonrpc: "2.0";
  id: number;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}

interface JSONRPCNotification {
  jsonrpc: "2.0";
  method: string;
  params?: unknown;
}

// MCP 客户端
class MCPClient {
  private process: any;
  private rl: any;
  private requestId = 0;
  private pendingRequests = new Map<number, { resolve: (value: any) => void; reject: (error: Error) => void }>();
  private initialized = false;

  constructor(private config: MCPServerConfig) {}

  async connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      const env = { ...process.env, ...this.config.env };
      this.process = spawn(this.config.command, this.config.args, { env, stdio: ["pipe", "pipe", "pipe"] });

      this.rl = createInterface({
        input: this.process.stdout,
        crlfDelay: Infinity,
      });

      this.rl.on("line", (line: string) => {
        try {
          const message = JSON.parse(line);
          if (message.id !== undefined) {
            const pending = this.pendingRequests.get(message.id);
            if (pending) {
              this.pendingRequests.delete(message.id);
              if (message.error) {
                pending.reject(new Error(message.error.message));
              } else {
                pending.resolve(message.result);
              }
            }
          }
        } catch (e) {
          // 忽略非 JSON 行
        }
      });

      this.process.stderr.on("data", (data: Buffer) => {
        console.error(`MCP stderr: ${data.toString()}`);
      });

      this.process.on("error", reject);
      this.process.on("exit", (code: number) => {
        console.log(`MCP process exited with code ${code}`);
      });

      resolve();
    });
  }

  async initialize(): Promise<void> {
    const result = await this.request("initialize", {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "pi-coding-agent", version: "0.76.0" },
    });

    await this.notify("notifications/initialized", {});
    this.initialized = true;
  }

  async listTools(): Promise<any[]> {
    const result = await this.request("tools/list", {});
    return result.tools || [];
  }

  async callTool(name: string, args: any): Promise<any> {
    return this.request("tools/call", { name, arguments: args });
  }

  private request(method: string, params: unknown): Promise<any> {
    const id = ++this.requestId;
    return new Promise((resolve, reject) => {
      this.pendingRequests.set(id, { resolve, reject });
      const request: JSONRPCRequest = {
        jsonrpc: "2.0",
        id,
        method,
        params,
      };
      this.process.stdin.write(JSON.stringify(request) + "\n");
    });
  }

  private notify(method: string, params: unknown): void {
    const notification: JSONRPCNotification = {
      jsonrpc: "2.0",
      method,
      params,
    };
    this.process.stdin.write(JSON.stringify(notification) + "\n");
  }

  disconnect(): void {
    this.process.kill();
  }
}

// 读取 MCP 配置
function loadMCPConfig(): MCPConfig | null {
  const configPaths = [
    join(homedir(), ".pi", "agent", "mcp-servers.json"),
    join(homedir(), ".pi", "agent", "mcp.json"),
  ];

  for (const path of configPaths) {
    if (existsSync(path)) {
      try {
        const content = readFileSync(path, "utf-8");
        return JSON.parse(content);
      } catch (e) {
        console.error(`Failed to read MCP config from ${path}: ${e}`);
      }
    }
  }

  return null;
}

// JSON Schema 到 TypeBox 的转换
function jsonSchemaToTypeBox(schema: any): any {
  if (!schema) return Type.Any();

  switch (schema.type) {
    case "object": {
      const props: Record<string, any> = {};
      for (const [key, value] of Object.entries(schema.properties || {})) {
        props[key] = jsonSchemaToTypeBox(value);
      }
      return Type.Object(props);
    }
    case "array":
      return Type.Array(jsonSchemaToTypeBox(schema.items || {}));
    case "string":
      return Type.String();
    case "number":
    case "integer":
      return Type.Number();
    case "boolean":
      return Type.Boolean();
    default:
      return Type.Any();
  }
}

// 扩展主函数
export default async function (pi: ExtensionAPI) {
  const config = loadMCPConfig();
  if (!config || !config.mcpServers) {
    console.log("No MCP servers configured. Create ~/.pi/agent/mcp-servers.json");
    return;
  }

  for (const [name, serverConfig] of Object.entries(config.mcpServers)) {
    if (serverConfig.enabled === false) continue;

    try {
      const client = new MCPClient({
        command: serverConfig.command,
        args: serverConfig.args,
        env: serverConfig.env,
      });

      await client.connect();
      await client.initialize();

      const tools = await client.listTools();

      for (const tool of tools) {
        pi.registerTool({
          name: tool.name,
          label: tool.description || tool.name,
          description: tool.description || "",
          parameters: jsonSchemaToTypeBox(tool.inputSchema),
          async execute(toolCallId, params, signal, onUpdate, ctx) {
            try {
              const result = await client.callTool(tool.name, params);
              return {
                content: result.content || [],
                details: result,
              };
            } catch (error) {
              return {
                content: [{ type: "text", text: `Error: ${error.message}` }],
                details: { error: error.message },
                isError: true,
              };
            }
          },
        });
      }

      console.log(`MCP server "${name}" connected: ${tools.length} tools registered`);
    } catch (error) {
      console.error(`Failed to connect to MCP server "${name}": ${error}`);
    }
  }
}
