```typescript
function jsonSchemaToType(schema: any, isRequired = true): any {
  if (!schema) return Type.Unknown();

  // 处理 $ref（简单情况）
  if (schema.$ref) {
    return Type.Unknown(); // 简化处理
  }

  // 处理 anyOf / oneOf
  if (schema.anyOf) {
    return Type.Union(schema.anyOf.map((s: any) => jsonSchemaToType(s)));
  }
  if (schema.oneOf) {
    return Type.Union(schema.oneOf.map((s: any) => jsonSchemaToType(s)));
  }

  // 处理 const
  if (schema.const !== undefined) {
    return Type.Literal(schema.const);
  }

  // 处理 enum
  if (schema.enum) {
    return Type.Union(schema.enum.map((v: any) => Type.Literal(v)));
  }

  switch (schema.type) {
    case "object": {
      const props: Record<string, any> = {};
      const required = new Set(schema.required || []);
      for (const [key, value] of Object.entries(schema.properties || {})) {
        props[key] = jsonSchemaToType(value, required.has(key));
      }
      return Type.Object(props);
    }
    case "array":
      return Type.Array(jsonSchemaToType(schema.items || {}));
    case "string":
      return Type.String();
    case "number":
    case "integer":
      return Type.Number();
    case "boolean":
      return Type.Boolean();
    case "null":
      return Type.Null();
    default:
      return Type.Unknown();
  }
}
