import type { ExtensionAPI, ToolResult } from "@earendil-works/pi-coding-agent";
import { Type, Static } from "typebox";
import { spawn, ChildProcess } from "child_process";
import { readFileSync, existsSync } from "fs";
import { join, homedir } from "path";

// ── MCP Config ──────────────────────────────────────────────
interface MCPServerConfig {
  command: string;
  args: string[];
  env?: Record<string, string>;
}

interface MCPConfigFile {
  mcpServers: Record<string, MCPServerConfig & { enabled?: boolean }>;
}

// ── JSON-RPC types ──────────────────────────────────────────
interface RPCRequest {
  jsonrpc: "2.0";
  id: number;
  method: string;
  params?: unknown;
}

interface RPCNotification {
  jsonrpc: "2.0";
  method: string;
  params?: unknown;
}

interface RPCResponse {
  jsonrpc: "2.0";
  id: number;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}

// ── MCP Client ──────────────────────────────────────────────
class MCPClient {
  private proc: ChildProcess | null = null;
  private buffer = "";
  private nextId = 1;
  private pending = new Map<number, {
    resolve: (v: unknown) => void;
    reject: (e: Error) => void;
  }>();

  constructor(private cfg: MCPServerConfig) {}

  async connect(): Promise<void> {
    const isWin = process.platform === "win32";
    const isCmd = this.cfg.command.toLowerCase().endsWith(".cmd") ||
                  this.cfg.command.toLowerCase().endsWith(".bat");

    let cmd: string;
    let args: string[];

    if (isWin && isCmd) {
      cmd = "cmd.exe";
      args = ["/c", this.cfg.command, ...this.cfg.args];
    } else {
      cmd = this.cfg.command;
      args = this.cfg.args;
    }

    const env = { ...process.env, ...this.cfg.env };

    this.proc = spawn(cmd, args, {
      env,
      stdio: ["pipe", "pipe", "pipe"],
    });

    this.proc.stdout!.on("data", (chunk: Buffer) => this.onData(chunk));
    this.proc.stderr!.on("data", (chunk: Buffer) => {
      // MCP servers often log debug info to stderr — forward to console
      console.error(`[MCP stderr] ${chunk.toString().trim()}`);
    });

    return new Promise((resolve, reject) => {
      this.proc!.on("error", reject);
      this.proc!.on("spawn", () => resolve());
    });
  }

  private onData(chunk: Buffer): void {
    this.buffer += chunk.toString();
    const lines = this.buffer.split("\n");
    this.buffer = lines.pop() || "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const msg: RPCResponse = JSON.parse(trimmed);
        if (msg.id !== undefined) {
          const p = this.pending.get(msg.id);
          if (p) {
            this.pending.delete(msg.id);
            if (msg.error) {
              p.reject(new Error(msg.error.message));
            } else {
              p.resolve(msg.result);
            }
          }
        }
      } catch {
        // ignore non-JSON lines (stderr leakage, etc.)
      }
    }
  }

  private send(obj: RPCRequest | RPCNotification): void {
    this.proc!.stdin!.write(JSON.stringify(obj) + "\n");
  }

  async request(method: string, params?: unknown): Promise<unknown> {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      const req: RPCRequest = { jsonrpc: "2.0", id, method, params };
      this.send(req);
      // 5 minute timeout
      setTimeout(() => {
        if (this.pending.has(id)) {
          this.pending.delete(id);
          reject(new Error(`MCP request timeout: ${method}`));
        }
      }, 5 * 60 * 1000);
    });
  }

  async initialize(): Promise<void> {
    await this.request("initialize", {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "pi-coding-agent", version: "0.76.0" },
    });
    this.send({
      jsonrpc: "2.0",
      method: "notifications/initialized",
    });
  }

  async listTools(): Promise<ToolEntry[]> {
    const res = (await this.request("tools/list", {})) as { tools?: ToolEntry[] };
    return res.tools || [];
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<ToolCallResult> {
    const res = await this.request("tools/call", { name, arguments: args });
    return res as ToolCallResult;
  }

  disconnect(): void {
    this.proc?.kill();
  }
}

interface ToolEntry {
  name: string;
  description?: string;
  inputSchema?: {
    type: "object";
    properties?: Record<string, unknown>;
    required?: string[];
  };
}

interface ToolCallResult {
  content?: Array<{ type: string; text?: string; [key: string]: unknown }>;
  isError?: boolean;
  [key: string]: unknown;
}

// ── JSON Schema → TypeBox converter ─────────────────────────
function schemaToType(schema: unknown): any {
  if (!schema || typeof schema !== "object") return Type.Unknown();
  const s = schema as Record<string, unknown>;

  if (s.enum) {
    const vals = s.enum as Array<string | number | boolean>;
    if (vals.every(v => typeof v === "string")) {
      return Type.String();
    }
    return Type.Union(vals.map(v => Type.Literal(v)));
  }

  if (s.const !== undefined) return Type.Literal(s.const);

  switch (s.type) {
    case "object": {
      const props: Record<string, any> = {};
      const req = new Set((s.required as string[]) || []);
      for (const [k, v] of Object.entries(s.properties || {})) {
        props[k] = req.has(k) ? schemaToType(v) : Type.Optional(schemaToType(v));
      }
      return Type.Object(props);
    }
    case "array":
      return Type.Array(schemaToType(s.items));
    case "string":  return Type.String();
    case "number":
    case "integer": return Type.Number();
    case "boolean": return Type.Boolean();
    case "null":    return Type.Null();
    default:        return Type.Unknown();
  }
}

// ── Load config ─────────────────────────────────────────────
function loadConfig(): MCPConfigFile | null {
  const paths = [
    join(homedir(), ".pi", "agent", "mcp-servers.json"),
  ];

  // Also check project-local config
  const cwd = process.cwd();
  paths.push(join(cwd, ".pi", "mcp-servers.json"));

  for (const p of paths) {
    if (existsSync(p)) {
      try {
        return JSON.parse(readFileSync(p, "utf-8"));
      } catch (e) {
        console.error(`[mcp] Failed to parse ${p}: ${e}`);
      }
    }
  }
  return null;
}

// ── Extension entry ─────────────────────────────────────────
export default async function (pi: ExtensionAPI) {
  const config = loadConfig();
  if (!config?.mcpServers) {
    return; // no MCP servers configured
  }

  const clients: { name: string; client: MCPClient }[] = [];

  pi.on("session_shutdown", async () => {
    for (const { client } of clients) {
      client.disconnect();
    }
  });

  for (const [name, srv] of Object.entries(config.mcpServers)) {
    if (srv.enabled === false) continue;

    try {
      const client = new MCPClient({
        command: srv.command,
        args: srv.args,
        env: srv.env,
      });

      await client.connect();
      await client.initialize();

      const tools = await client.listTools();

      for (const tool of tools) {
        pi.registerTool({
          name: tool.name,
          label: tool.description || tool.name,
          description: tool.description || `MCP tool: ${tool.name}`,
          parameters: schemaToType(tool.inputSchema),
          async execute(_toolCallId, params, _signal, _onUpdate, _ctx): Promise<ToolResult> {
            try {
              const result = await client.callTool(tool.name, params as Record<string, unknown>);
              const content = result.content || [];
              return {
                content: content.map((c: any) => ({
                  type: c.type || "text",
                  text: c.text || JSON.stringify(c),
                })),
                details: { source: name, tool: tool.name },
                isError: result.isError || false,
              };
            } catch (err: any) {
              return {
                content: [{ type: "text", text: `MCP tool "${tool.name}" failed: ${err.message}` }],
                details: { source: name, tool: tool.name, error: err.message },
                isError: true,
              };
            }
          },
        });
      }

      clients.push({ name, client });
      console.log(`[mcp] "${name}" connected — ${tools.length} tool(s) registered`);
    } catch (err: any) {
      console.error(`[mcp] Failed to connect "${name}": ${err.message}`);
    }
  }
}
